import { writeFileSync } from 'node:fs';
const s = [];
for (const c of ['-', '*', '_']) {
  for (const gap of [0, 1, 2, 3]) {
    for (const n of [1, 2, 3, 4]) {
      s.push('\n' + Array(n).fill(c).join(' '.repeat(gap)));
    }
  }
}
// run-length variants: two runs of length a and b separated by gap
for (const c of ['-', '*', '_']) {
  for (const gap of [1, 2, 3]) {
    for (const [a, b] of [[1,1],[1,2],[2,1],[2,2],[1,3],[3,1]]) {
      s.push('\n' + c.repeat(a) + ' '.repeat(gap) + c.repeat(b));
    }
  }
}
writeFileSync('/workspace/probes/hr-11.json', JSON.stringify(s));
console.log(s.length);

